function c({nodes:s,links:r}){const n=[];for(const i of s)i.reflexive&&n.push({from:i.id,to:i.id,weight:1});for(const i of r){const o=i.weight??1,e=i.source,t=i.target;i.right&&n.push({from:e,to:t,weight:o}),i.left&&n.push({from:t,to:e,weight:o})}return n}function d(s){const{nodes:r,links:n}=s,i={};for(const o of r)i[o.id]=[];for(const o of c({nodes:r,links:n})){const e=i[o.from],t=e.find(f=>f.id===o.to);t?t.weight=o.weight:e.push({id:o.to,weight:o.weight})}return[...r].sort((o,e)=>o.id-e.id).map(o=>({id:o.id,neighbors:[...i[o.id]].sort((e,t)=>e.id-t.id)}))}function g(s){const{nodes:r,links:n,allowWeight:i}=s,o=[...r].map(t=>t.id).sort((t,f)=>t-f),e={};for(const t of o){e[t]={};for(const f of o)e[t][f]=0}for(const t of c({nodes:r,links:n}))e[t.from][t.to]=i?t.weight:1;return{vertexIds:o,matrix:e}}function u(s){return c(s).sort((r,n)=>r.from!==n.from?r.from-n.from:r.to-n.to)}export{g as a,d as b,u as c};
